select unit_price_bucket, quantity_bucket, cnt from (select case when unit_price >= 440 then 'high' when unit_price >= 180 then 'mid' else 'low' end as unit_price_bucket, case when quantity >= 8 then 'high' when quantity >= 3 then 'mid' else 'low' end as quantity_bucket, count(*) as cnt from order_items group by case when unit_price >= 440 then 'high' when unit_price >= 180 then 'mid' else 'low' end, case when quantity >= 8 then 'high' when quantity >= 3 then 'mid' else 'low' end) as s where cnt >= 6
